/**
 * Ratchets down the goal by reducing the safety buffer (do-more goals) or hard cap (do-less goals), moving the bright red line closer to current data and making the goal harder.
 *
 * - Do More / Odometer / Gain Weight goals: `newsafety` is the number of days of safety buffer to ratchet down to.
 * - Do Less / Whittle Down goals: `newsafety` is the number of units of buffer (distance, in the goal's units, between the current total and the bright red line). It is relative to the bright red line, not the absolute hard-cap total.
 *
 * If the goal is on a flat spot (e.g. a scheduled break starting tomorrow), `newsafety` is clamped to a minimum of 1 day; the request still returns 200 but the resulting buffer may be larger than requested.
 *
 * Rule: when `newsafety` is 0, `beemergency` must also be sent as `true`, otherwise the request fails with an error.
 *
 * Documented error messages (returned in the `errors` field): "newsafety parameter is required", "newsafety must be a number", "newsafety cannot be negative", "newsafety cannot exceed X", "Ratcheting to 0 days of buffer requires beemergency=True on the API call", "Goal cannot be ratcheted because it is non-monotonic in the next N days", "Goal cannot be ratcheted (may be archived, ended, or have no buffer)", "Failed to ratchet goal".
 * @summary Ratchet a goal
 */
export const ratchetGoal = async (username: string,
    slug: string,
    ratchetGoalBody: RatchetGoalBody, options?: Parameters<typeof http>[1]): Promise<ratchetGoalResponse> => {

  return http<ratchetGoalResponse>(getRatchetGoalUrl(username,slug),
  {
    ...options,
    method: 'POST',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(ratchetGoalBody)
  }
);}


